fn permission_denied(dir: impl AsRef<Path>) -> bool {
    match dir.as_ref().read_dir() {
        Err(e) => matches!(e.kind(), std::io::ErrorKind::PermissionDenied),
        Ok(_) => false,
    }
}

fn is_empty_dir(dir: impl AsRef<Path>) -> bool {
    match dir.as_ref().read_dir() {
        Err(_) => true,
        Ok(mut s) => s.next().is_none(),
    }
}

fn is_hidden_dir(dir: impl AsRef<Path>) -> bool {
    #[cfg(windows)]
    {
        use std::os::windows::fs::MetadataExt;

        if let Ok(metadata) = dir.as_ref().metadata() {
            let attributes = metadata.file_attributes();
            // https://docs.microsoft.com/en-us/windows/win32/fileio/file-attribute-constants
            (attributes & 0x2) != 0
        } else {
            false
        }
    }

    #[cfg(not(windows))]
    {
        dir.as_ref()
            .file_name()
            .map(|name| name.to_string_lossy().starts_with('.'))
            .unwrap_or(false)
    }
}

fn path_contains_hidden_folder(path: &Path, folders: &[PathBuf]) -> bool {
    if folders.iter().any(|p| path.starts_with(p.as_path())) {
        return true;
    }
    false
}

#[cfg(unix)]
use std::os::unix::fs::FileTypeExt;
use std::path::Path;

pub fn get_file_type(md: &std::fs::Metadata, display_name: &str, use_mime_type: bool) -> String {
    let ft = md.file_type();
    let mut file_type = "unknown";
    if ft.is_dir() {
        file_type = "dir";
    } else if ft.is_file() {
        file_type = "file";
    } else if ft.is_symlink() {
        file_type = "symlink";
    } else {
        #[cfg(unix)]
        {
            if ft.is_block_device() {
                file_type = "block device";
            } else if ft.is_char_device() {
                file_type = "char device";
            } else if ft.is_fifo() {
                file_type = "pipe";
            } else if ft.is_socket() {
                file_type = "socket";
            }
        }
    }
    if use_mime_type {
        let display_path = Path::new(display_name);
        let normalized = expand_to_real_path(display_path);
        let original_extension = display_path
            .extension()
            .and_then(|ext| ext.to_str());
        let normalized_extension = normalized
            .extension()
            .and_then(|ext| ext.to_str());
        let mime_path = if original_extension == normalized_extension {
            normalized.as_path()
        } else {
            display_path
        };
        let file_name = mime_path
            .file_name()
            .and_then(|name| name.to_str())
            .unwrap_or(display_name);
        let parts: Vec<&str> = file_name.split('.').collect();
        let mut extensions: Vec<String> = Vec::new();
        let mut current_extension = String::new();
        for part in parts.iter().rev() {
            if current_extension.is_empty() {
                current_extension.push_str(part);
            } else {
                current_extension = format!("{}.{}", part, current_extension);
            }
            extensions.push(current_extension.clone());
        }
        if !extensions.is_empty() {
            extensions.pop();
            extensions.reverse();
        }
        let path_ext = mime_path
            .extension()
            .and_then(|ext| ext.to_str())
            .unwrap_or("");
        let mut resolved_ext = path_ext;
        if !path_ext.is_empty() {
            for ext in &extensions {
                if ext == path_ext {
                    resolved_ext = ext.as_str();
                }
            }
        }
        let mime_guess = if resolved_ext.is_empty() {
            "unknown".to_string()
        } else {
            match mime_guess::from_ext(resolved_ext).first() {
                Some(mime_type) => mime_type.essence_str().to_string(),
                None => "unknown".to_string(),
            }
        };
        if file_type == "file" {
            mime_guess
        } else {
            file_type.to_string()
        }
    } else {
        file_type.to_string()
    }
}

